-- Expected: BUILD FAIL (type varchar not supported as partition key for RANGE)
CREATE TABLE t1_tc_pa0055 (id INT NOT NULL AUTO_INCREMENT, target VARCHAR(63), pad VARCHAR(10), PRIMARY KEY(id)) ENGINE=InnoDB PARTITION BY RANGE(target) PARTITIONS 2;
-- If above succeeded, ALTER should also FAIL (partition key column cannot be modified)
ALTER TABLE t1_tc_pa0055 MODIFY target VARCHAR(64) CHARACTER SET utf8mb4, ALGORITHM=instant;
SELECT 'TC-PA0055' AS test_id, 'BUILD_OR_ALTER_FAIL_EXPECTED' AS result, 'CHECK_MANUALLY' AS note;

