   WHERE id NOT IN (SELECT id FROM t2_tc_qa0056)
  UNION ALL
  SELECT 't2_extra' AS src, id FROM t2_tc_qa0056
   WHERE id NOT IN (SELECT id FROM t1_tc_qa0056)
  UNION ALL
  SELECT 'data_mismatch' AS src, a.id FROM t1_tc_qa0056 a JOIN t2_tc_qa0056 b ON a.id = b.id
   WHERE NOT (a.id <=> b.id AND a.pad1 <=> b.pad1 AND a.target <=> b.target AND a.pad2 <=> b.pad2)
) AS mismatches;

