-- Partition: RANGE + RANGE COLUMNS (PP-02)
-- Target is partition key: False
DROP TABLE IF EXISTS t1_tc_qa0100, t2_tc_qa0100;
-- Expected: CREATE OK, ALTER SUCCESS
CREATE TABLE t1_tc_qa0100 (
  id INT NOT NULL AUTO_INCREMENT,
  pad1 VARCHAR(20) DEFAULT 'pad1',
  target INT UNSIGNED,
  pad2 VARCHAR(20) DEFAULT 'pad2', PRIMARY KEY (id), INDEX idx_pad1 (pad1)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC
PARTITION BY RANGE (id) (
  PARTITION p0 VALUES LESS THAN (100),
  PARTITION p1 VALUES LESS THAN (200),
  PARTITION p2 VALUES LESS THAN (300),
  PARTITION p3 VALUES LESS THAN MAXVALUE
);
