-- ALTER expected SUCCESS
ALTER TABLE t1_tc_qa0100 MODIFY target BIGINT UNSIGNED, ALGORITHM=instant;
INSERT INTO t1_tc_qa0100 (target) VALUES (18446744073709551615);
INSERT INTO t1_tc_qa0100 (target) VALUES (18446744073709551614);
INSERT INTO t1_tc_qa0100 (target) VALUES (4294967296);
