INSERT INTO t1_tc_qa0100 (target) VALUES (1);
CREATE TABLE t2_tc_qa0100 (
  id INT NOT NULL AUTO_INCREMENT,
  pad1 VARCHAR(20) DEFAULT 'pad1',
  target BIGINT UNSIGNED,
  pad2 VARCHAR(20) DEFAULT 'pad2', PRIMARY KEY (id), INDEX idx_pad1 (pad1)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC;
INSERT INTO t2_tc_qa0100 (target) VALUES (0);
INSERT INTO t2_tc_qa0100 (target) VALUES (4294967295);
INSERT INTO t2_tc_qa0100 (target) VALUES (4294967294);
INSERT INTO t2_tc_qa0100 (target) VALUES (1);
