-- Partition: LIST + LINEAR HASH (PP-22)
-- Target is partition key: True
DROP TABLE IF EXISTS t1_tc_pa1299, t2_tc_pa1299;
-- Expected: CREATE OK, ALTER FAIL (partition key cannot be modified)
CREATE TABLE t1_tc_pa1299 (
  id INT NOT NULL AUTO_INCREMENT,
  target INT UNSIGNED,
  pad VARCHAR(20) DEFAULT 'pad',
  PRIMARY KEY (id, target)
) ENGINE=InnoDB
PARTITION BY LIST (target) (
  PARTITION p0 VALUES IN (0,1,2,3),
  PARTITION p1 VALUES IN (4,5,6,7),
  PARTITION p2 VALUES IN (8,9,10,11),
  PARTITION p3 VALUES IN (12,13,14,15)
);
INSERT INTO t1_tc_pa1299 (target) VALUES (0);
INSERT INTO t1_tc_pa1299 (target) VALUES (4294967295);
INSERT INTO t1_tc_pa1299 (target) VALUES (4294967294);
-- ALTER expected to FAIL
ALTER TABLE t1_tc_pa1299 MODIFY target BIGINT UNSIGNED, ALGORITHM=instant;
CREATE TABLE t2_tc_pa1299 (
  id INT NOT NULL AUTO_INCREMENT,
  pad1 VARCHAR(20) DEFAULT 'pad1',
  target INT UNSIGNED,
  pad2 VARCHAR(20) DEFAULT 'pad2', PRIMARY KEY (id), INDEX idx_pad1 (pad1)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC;
INSERT INTO t2_tc_pa1299 (target) VALUES (0);
INSERT INTO t2_tc_pa1299 (target) VALUES (4294967295);
INSERT INTO t2_tc_pa1299 (target) VALUES (4294967294);
SELECT 'TC-PA1299' AS test_id,
       IF(COUNT(*)=0,'PASS','FAIL') AS result,
       IF(COUNT(*)=0,'',GROUP_CONCAT(CONCAT(src,':id=',id) SEPARATOR '; ')) AS mismatch
FROM (
  SELECT 't1_extra' AS src, id FROM t1_tc_pa1299
   WHERE id NOT IN (SELECT id FROM t2_tc_pa1299)
  UNION ALL
  SELECT 't2_extra' AS src, id FROM t2_tc_pa1299
   WHERE id NOT IN (SELECT id FROM t1_tc_pa1299)
  UNION ALL
  SELECT 'data_mismatch' AS src, a.id FROM t1_tc_pa1299 a JOIN t2_tc_pa1299 b ON a.id = b.id
   WHERE NOT (a.id <=> b.id AND a.target <=> b.target AND a.pad <=> b.pad)
) AS mismatches;

