  pad1 VARCHAR(20) DEFAULT 'pad1',
  target VARCHAR(85) CHARACTER SET utf8,
  pad2 VARCHAR(20) DEFAULT 'pad2', PRIMARY KEY (id), INDEX idx_pad1 (pad1)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARSET=utf8;
INSERT INTO t2_tc_pa1793 (target) VALUES ('');
INSERT INTO t2_tc_pa1793 (target) VALUES ('a');
INSERT INTO t2_tc_pa1793 (target) VALUES ('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx');
SELECT 'TC-PA1793' AS test_id,
       IF(COUNT(*)=0,'PASS','FAIL') AS result,
       IF(COUNT(*)=0,'',GROUP_CONCAT(CONCAT(src,':id=',id) SEPARATOR '; ')) AS mismatch
FROM (
  SELECT 't1_extra' AS src, id FROM t1_tc_pa1793
   WHERE id NOT IN (SELECT id FROM t2_tc_pa1793)
  UNION ALL
  SELECT 't2_extra' AS src, id FROM t2_tc_pa1793
   WHERE id NOT IN (SELECT id FROM t1_tc_pa1793)
  UNION ALL
  SELECT 'data_mismatch' AS src, a.id FROM t1_tc_pa1793 a JOIN t2_tc_pa1793 b ON a.id = b.id
   WHERE NOT (a.id <=> b.id AND a.target <=> b.target AND a.pad <=> b.pad)
) AS mismatches;

