-- Partition: LINEAR KEY + RANGE COLUMNS (PP-58)
-- Target is partition key: True
DROP TABLE IF EXISTS t1_tc_pa3469, t2_tc_pa3469;
-- Expected: CREATE OK, ALTER FAIL (partition key cannot be modified)
CREATE TABLE t1_tc_pa3469 (
  id INT NOT NULL AUTO_INCREMENT,
  target VARCHAR(254),
  pad VARCHAR(20) DEFAULT 'pad',
  PRIMARY KEY (id, target)
) ENGINE=InnoDB
PARTITION BY LINEAR KEY(id) PARTITIONS 4;
INSERT INTO t1_tc_pa3469 (target) VALUES ('');
INSERT INTO t1_tc_pa3469 (target) VALUES ('a');
INSERT INTO t1_tc_pa3469 (target) VALUES ('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx');
-- ALTER expected to FAIL
ALTER TABLE t1_tc_pa3469 MODIFY target VARCHAR(255) CHARACTER SET latin1, ALGORITHM=instant;
CREATE TABLE t2_tc_pa3469 (
  id INT NOT NULL AUTO_INCREMENT,
  pad1 VARCHAR(20) DEFAULT 'pad1',
  target VARCHAR(254) CHARACTER SET latin1,
  pad2 VARCHAR(20) DEFAULT 'pad2', PRIMARY KEY (id), INDEX idx_pad1 (pad1)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARSET=latin1;
INSERT INTO t2_tc_pa3469 (target) VALUES ('');
INSERT INTO t2_tc_pa3469 (target) VALUES ('a');
INSERT INTO t2_tc_pa3469 (target) VALUES ('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx');
SELECT 'TC-PA3469' AS test_id,
       IF(COUNT(*)=0,'PASS','FAIL') AS result,
       IF(COUNT(*)=0,'',GROUP_CONCAT(CONCAT(src,':id=',id) SEPARATOR '; ')) AS mismatch
FROM (
  SELECT 't1_extra' AS src, id FROM t1_tc_pa3469
   WHERE id NOT IN (SELECT id FROM t2_tc_pa3469)
  UNION ALL
  SELECT 't2_extra' AS src, id FROM t2_tc_pa3469
   WHERE id NOT IN (SELECT id FROM t1_tc_pa3469)
  UNION ALL
  SELECT 'data_mismatch' AS src, a.id FROM t1_tc_pa3469 a JOIN t2_tc_pa3469 b ON a.id = b.id
   WHERE NOT (a.id <=> b.id AND a.target <=> b.target AND a.pad <=> b.pad)
) AS mismatches;

