  UNION ALL
  SELECT 'data_mismatch' AS src, a.id FROM t1_tc_qa0250 a JOIN t2_tc_qa0250 b ON a.id = b.id
   WHERE NOT (a.id <=> b.id AND a.pad1 <=> b.pad1 AND a.target <=> b.target AND a.pad2 <=> b.pad2)
) AS mismatches;

