CREATE TABLE t2_tc_qa0556 (
  id INT NOT NULL AUTO_INCREMENT,
  pad1 VARCHAR(20) DEFAULT 'pad1',
  target INT,
  pad2 VARCHAR(20) DEFAULT 'pad2', PRIMARY KEY (id), INDEX idx_pad1 (pad1)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC;
INSERT INTO t2_tc_qa0556 (target) VALUES (-8388608);
INSERT INTO t2_tc_qa0556 (target) VALUES (8388607);
INSERT INTO t2_tc_qa0556 (target) VALUES (-8388607);
