SELECT 'TC-QA0556' AS test_id,
       IF(COUNT(*)=0,'PASS','FAIL') AS result,
       IF(COUNT(*)=0,'',GROUP_CONCAT(CONCAT(src,':id=',id) SEPARATOR '; ')) AS mismatch
FROM (
  SELECT 't1_extra' AS src, id FROM t1_tc_qa0556
   WHERE id NOT IN (SELECT id FROM t2_tc_qa0556)
  UNION ALL
  SELECT 't2_extra' AS src, id FROM t2_tc_qa0556
   WHERE id NOT IN (SELECT id FROM t1_tc_qa0556)
  UNION ALL
  SELECT 'data_mismatch' AS src, a.id FROM t1_tc_qa0556 a JOIN t2_tc_qa0556 b ON a.id = b.id
   WHERE NOT (a.id <=> b.id AND a.pad1 <=> b.pad1 AND a.target <=> b.target AND a.pad2 <=> b.pad2)
) AS mismatches;

