SELECT 'TC-PA1669' AS test_id,
       IF(COUNT(*)=0,'PASS','FAIL') AS result,
       IF(COUNT(*)=0,'',GROUP_CONCAT(CONCAT(src,':id=',id) SEPARATOR '; ')) AS mismatch
FROM (
  SELECT 't1_extra' AS src, id FROM t1_tc_pa1669
   WHERE id NOT IN (SELECT id FROM t2_tc_pa1669)
  UNION ALL
  SELECT 't2_extra' AS src, id FROM t2_tc_pa1669
   WHERE id NOT IN (SELECT id FROM t1_tc_pa1669)
  UNION ALL
  SELECT 'data_mismatch' AS src, a.id FROM t1_tc_pa1669 a JOIN t2_tc_pa1669 b ON a.id = b.id
   WHERE NOT (a.id <=> b.id AND a.target <=> b.target AND a.pad <=> b.pad)
) AS mismatches;

