-- Partition: HASH + LINEAR KEY (PP-40)
-- Target is partition key: False
DROP TABLE IF EXISTS t1_tc_qa2350, t2_tc_qa2350;
-- Expected: CREATE OK, ALTER SUCCESS
CREATE TABLE t1_tc_qa2350 (
  id INT NOT NULL AUTO_INCREMENT,
  pad1 VARCHAR(20) DEFAULT 'pad1',
  target SMALLINT,
  pad2 VARCHAR(20) DEFAULT 'pad2', PRIMARY KEY (id), INDEX idx_pad1 (pad1)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC
PARTITION BY HASH(id) PARTITIONS 4;
INSERT INTO t1_tc_qa2350 (target) VALUES (-32768);
INSERT INTO t1_tc_qa2350 (target) VALUES (32767);
INSERT INTO t1_tc_qa2350 (target) VALUES (-32767);
INSERT INTO t1_tc_qa2350 (target) VALUES (32766);
INSERT INTO t1_tc_qa2350 (target) VALUES (0);
-- ALTER expected SUCCESS
ALTER TABLE t1_tc_qa2350 MODIFY target MEDIUMINT, ALGORITHM=inplace;
INSERT INTO t1_tc_qa2350 (target) VALUES (-8388608);
INSERT INTO t1_tc_qa2350 (target) VALUES (-8388607);
INSERT INTO t1_tc_qa2350 (target) VALUES (8388607);
INSERT INTO t1_tc_qa2350 (target) VALUES (0);
INSERT INTO t1_tc_qa2350 (target) VALUES (1);
CREATE TABLE t2_tc_qa2350 (
  id INT NOT NULL AUTO_INCREMENT,
  pad1 VARCHAR(20) DEFAULT 'pad1',
  target MEDIUMINT,
  pad2 VARCHAR(20) DEFAULT 'pad2', PRIMARY KEY (id), INDEX idx_pad1 (pad1)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC;
INSERT INTO t2_tc_qa2350 (target) VALUES (-32768);
INSERT INTO t2_tc_qa2350 (target) VALUES (32767);
INSERT INTO t2_tc_qa2350 (target) VALUES (-32767);
INSERT INTO t2_tc_qa2350 (target) VALUES (32766);
INSERT INTO t2_tc_qa2350 (target) VALUES (0);
INSERT INTO t2_tc_qa2350 (target) VALUES (-8388608);
INSERT INTO t2_tc_qa2350 (target) VALUES (-8388607);
INSERT INTO t2_tc_qa2350 (target) VALUES (8388607);
INSERT INTO t2_tc_qa2350 (target) VALUES (0);
INSERT INTO t2_tc_qa2350 (target) VALUES (1);
SELECT 'TC-QA2350' AS test_id,
       IF(COUNT(*)=0,'PASS','FAIL') AS result,
       IF(COUNT(*)=0,'',GROUP_CONCAT(CONCAT(src,':id=',id) SEPARATOR '; ')) AS mismatch
FROM (
  SELECT 't1_extra' AS src, id FROM t1_tc_qa2350
   WHERE id NOT IN (SELECT id FROM t2_tc_qa2350)
  UNION ALL
  SELECT 't2_extra' AS src, id FROM t2_tc_qa2350
   WHERE id NOT IN (SELECT id FROM t1_tc_qa2350)
  UNION ALL
  SELECT 'data_mismatch' AS src, a.id FROM t1_tc_qa2350 a JOIN t2_tc_qa2350 b ON a.id = b.id
   WHERE NOT (a.id <=> b.id AND a.pad1 <=> b.pad1 AND a.target <=> b.target AND a.pad2 <=> b.pad2)
) AS mismatches;

